11  export async function handleWebhook(event: StoreEvent) {
12    if (await db.storeEvents.seen(event.id)) return;
13    await db.storeEvents.record(event.id, event.type);
14    switch (event.type) {
15      case "PURCHASE": return handlePurchase(event);
16      case "RENEWAL": return handleRenewal(event);
17      case "PAYMENT_FAILED": return handlePaymentFailed(event);
18      case "REFUND": return handleRefund(event);
19      case "CANCEL": return handleCancel(event);
20      default:
21        log.warn("store webhook: unknown type", { type: event.type });
22    }
23  }
