25  async function handlePurchase(event: StoreEvent) {
26    const user = await db.users.byStoreAccount(event.accountId);
27    if (!user) {
28      log.warn("store webhook: purchase for unknown account", { accountId: event.accountId });
29      return;
30    }
31    await db.subscriptions.upsert({
32      userId: user.id,
33      storeId: event.subscriptionId,
34      plan: event.productId,
35      status: "active",
36      renewsAt: event.expiresAt,
37    });
38    await notify(user.id, "subscription_started");
39  }
40
41  async function handleRenewal(event: StoreEvent) {
42    const sub = await db.subscriptions.byStoreId(event.subscriptionId);
43    if (!sub) return;
44    // a renewal after a failed payment also ends the grace period
45    await db.subscriptions.update(sub.id, { status: "active", renewsAt: event.expiresAt, graceUntil: null });
46  }
47
48  async function handleRefund(event: StoreEvent) {
49    const sub = await db.subscriptions.byStoreId(event.subscriptionId);
50    if (!sub) return;
51    await db.subscriptions.update(sub.id, { status: "refunded", endedAt: event.at });
52    await notify(sub.userId, "subscription_refunded");
53  }
54
55  async function handleCancel(event: StoreEvent) {
56    const sub = await db.subscriptions.byStoreId(event.subscriptionId);
57    if (!sub) return;
58    // keeps access until the end of the paid period
59    await db.subscriptions.update(sub.id, { status: "canceled", endsAt: event.expiresAt });
60  }
