62  // Renewal payment failed: the store retries for a few days.
63  async function handlePaymentFailed(event: StoreEvent) {
64    const sub = await db.subscriptions.byStoreId(event.subscriptionId);
65    if (!sub) return;
66    // grace period: 3 days of access while the store retries
67    await db.subscriptions.update(sub.id, { status: "grace", graceUntil: addDays(event.at, 3) });
68    await notify(sub.userId, "payment_failed");
69    // no retry count kept: after the store gives up we never move it to 'expired'
70  }
