10  export async function claim(limit = 20) {
11    return sql`
12      -- claim due jobs: FOR UPDATE SKIP LOCKED
13      UPDATE outbox SET locked_at = now(), attempts = attempts + 1
14      WHERE id IN (
15        SELECT id FROM outbox WHERE run_at <= now() AND done_at IS NULL
16        ORDER BY run_at FOR UPDATE SKIP LOCKED LIMIT ${limit}
17      ) RETURNING *`;
